WITH flattened AS (SELECT id, service, host, level, latency_ms, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, attr_value) SELECT id, service, host, level, attr_key, STDDEV_SAMP(latency_ms) OVER w_ordered AS level_stddev_samp_latency_ms, AVG(latency_ms) OVER w_part AS latency_ms_avg_2_prior, NTILE(3) OVER w_part_2 AS latency_ms_bucket, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host, level), 4) AS latency_ms_share FROM flattened WHERE host <> 'h1' WINDOW w_ordered AS (PARTITION BY level), w_part AS (PARTITION BY level ORDER BY latency_ms, id, attr_key ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_part_2 AS (PARTITION BY service ORDER BY latency_ms DESC, id, attr_key)
